	private void rebuildStatusRows()
	{
		statusRowsPanel.removeAll();

		addStatusRow("Bank", plugin.getSnapshot(StorageLocation.BANK));

		Map<StorageLocation, StorageSnapshot> pohSnapshots = plugin.getSnapshots();
		Map<StorageLocation, StorageSnapshot> safeMap = pohSnapshots == null
				? new EnumMap<>(StorageLocation.class)
				: pohSnapshots;

		for (StorageLocation location : StorageLocation.values())
		{
			if (location == StorageLocation.BANK)
			{
				continue;
			}

			addStatusRow(prettyLocation(location), safeMap.get(location));
		}

		statusRowsPanel.revalidate();
		statusRowsPanel.repaint();
	}

	private void addStatusRow(String label, StorageSnapshot snapshot)
	{
		DataFreshness freshness = getFreshness(snapshot);

		JPanel row = new JPanel(new BorderLayout(8, 0));
		row.setBackground(CARD_BG);
		row.setBorder(BorderFactory.createEmptyBorder(3, 0, 3, 0));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 22));

		JLabel left = new JLabel(label);
		left.setForeground(HEADER);
		left.setFont(left.getFont().deriveFont(12f));

		JLabel right = new JLabel(formatFreshness(freshness));
		right.setForeground(colorForFreshness(freshness));
		right.setFont(right.getFont().deriveFont(java.awt.Font.BOLD, 11f));
		right.setHorizontalAlignment(SwingConstants.RIGHT);
		right.setPreferredSize(new Dimension(90, 18));

		row.add(left, BorderLayout.CENTER);
		row.add(right, BorderLayout.EAST);

		statusRowsPanel.add(row);
	}

	private DataFreshness getFreshness(StorageSnapshot snapshot)
	{
		if (snapshot == null || snapshot.getMetadata() == null)
		{
			return DataFreshness.NEVER_SEEN;
		}

		SnapshotMetadata metadata = snapshot.getMetadata();
		if (metadata.getLastUpdated() <= 0)
		{
			return DataFreshness.NEVER_SEEN;
		}

		long now = System.currentTimeMillis();
		long ageMillis = Math.max(0, now - metadata.getLastUpdated());
		long hours = ageMillis / (1000L * 60L * 60L);

		if (hours < config.warningAfterHours())
		{
			return DataFreshness.FRESH;
		}
		else if (hours < config.staleAfterHours())
		{
			return DataFreshness.MAYBE_STALE;
		}
		else
		{
			return DataFreshness.OUT_OF_DATE;
		}
	}

	private String formatFreshness(DataFreshness freshness)
	{
		switch (freshness)
		{
			case FRESH:
				return "Fresh";
			case MAYBE_STALE:
				return "Maybe stale";
			case OUT_OF_DATE:
				return "Out of date";
			case NEVER_SEEN:
			default:
				return "Never seen";
		}
	}

	private Color colorForFreshness(DataFreshness freshness)
	{
		switch (freshness)
		{
			case FRESH:
				return FRESH_COLOR;
			case MAYBE_STALE:
				return MAYBE_STALE_COLOR;
			case OUT_OF_DATE:
				return OUT_OF_DATE_COLOR;
			case NEVER_SEEN:
			default:
				return NEVER_SEEN_COLOR;
		}
	}

	private String prettyLocation(StorageLocation location)
	{
		String raw = Objects.toString(location, "");
		raw = raw.replace('_', ' ').toLowerCase();

		StringBuilder sb = new StringBuilder(raw.length());
		boolean capitalize = true;

		for (char c : raw.toCharArray())
		{
			if (capitalize && Character.isLetter(c))
			{
				sb.append(Character.toUpperCase(c));
				capitalize = false;
			}
			else
			{
				sb.append(c);
			}

			if (c == ' ')
			{
				capitalize = true;
			}
		}

		return sb.toString();
	}

	private void startAutoRefreshTimer()
	{
		Timer timer = new Timer(30_000, e -> refresh());
		timer.setRepeats(true);
		timer.start();
	}

	private static class DisabledSelectionModel extends DefaultListSelectionModel
	{
		@Override
		public void setSelectionInterval(int index0, int index1)
		{
		}

		@Override
		public void addSelectionInterval(int index0, int index1)
		{
		}
	}
}

package com.wheresmystuff;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashMap;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Set;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;

@Singleton
public class PohStorageScanner
{
	private static final int MAX_ROOT_CHILDREN = 256;

	private static final int POH_GROUP_A = 674;
	private static final int POH_GROUP_B = 675;

	private final Client client;

	@Inject
	public PohStorageScanner(Client client)
	{
		this.client = client;
	}

	public Optional<ScanResult> scanLoadedGroup(int groupId)
	{
		if (groupId != POH_GROUP_A && groupId != POH_GROUP_B)
		{
			return Optional.empty();
		}

		List<Widget> roots = getRootWidgets(groupId);
		if (roots.isEmpty())
		{
			return Optional.empty();
		}

		String allText = collectLowercaseText(roots);
		StorageLocation location = detectLocationFromText(allText);

		if (location == null || !location.isPoh())
		{
			return Optional.empty();
		}

		Map<Integer, Integer> quantities = extractItemQuantities(roots);
		return Optional.of(new ScanResult(location, quantities));
	}

	private List<Widget> getRootWidgets(int groupId)
	{
		List<Widget> roots = new ArrayList<>();

		for (int childId = 0; childId < MAX_ROOT_CHILDREN; childId++)
		{
			Widget widget = client.getWidget(groupId, childId);
			if (widget != null)
			{
				roots.add(widget);
			}
		}

		return roots;
	}

	private StorageLocation detectLocationFromText(String allText)
	{
		if (allText == null)
		{
			return null;
		}

		String text = allText.toLowerCase(Locale.ENGLISH);

		if (text.contains("magic wardrobe"))
		{
			return StorageLocation.MAGIC_WARDROBE;
		}

		if (text.contains("toy box"))
		{
			return StorageLocation.TOY_BOX;
		}

		if (text.contains("cape rack"))
		{
			return StorageLocation.CAPE_RACK;
		}

		if (text.contains("treasure chest"))
		{
			return StorageLocation.TREASURE_CHEST;
		}

		if (text.contains("armour case") || text.contains("armor case"))
		{
			return StorageLocation.ARMOUR_CASE;
		}

		if (text.contains("bookcase") || text.contains("bookshelf"))
		{
			return StorageLocation.BOOKCASE;
		}

		if (text.contains("fancy dress box"))
		{
			return StorageLocation.COSTUME_ROOM;
		}

		return null;
	}

	private String collectLowercaseText(List<Widget> roots)
	{
		StringBuilder sb = new StringBuilder();

		for (Widget root : roots)
		{
			for (Widget widget : traverse(root))
			{
				String text = widget.getText();
				if (text != null && !text.isEmpty())
				{
					sb.append(' ')
							.append(stripTags(text).toLowerCase(Locale.ENGLISH));
				}

				String name = widget.getName();
				if (name != null && !name.isEmpty())
				{
					sb.append(' ')
							.append(stripTags(name).toLowerCase(Locale.ENGLISH));
				}
			}
		}

		return sb.toString();
	}

	private Map<Integer, Integer> extractItemQuantities(List<Widget> roots)
	{
		Map<Integer, Integer> quantities = new HashMap<>();

		for (Widget root : roots)
		{
			for (Widget widget : traverse(root))
			{
				if (widget == null || widget.isHidden())
				{
					continue;
				}

				int itemId = widget.getItemId();
				if (itemId <= 0)
				{
					continue;
				}


				if (widget.getOpacity() > 0)
				{
					continue;
				}

				quantities.put(itemId, 1);
			}
		}

		return quantities;
	}


	private List<Widget> traverse(Widget root)
	{
		List<Widget> widgets = new ArrayList<>();
		Deque<Widget> queue = new ArrayDeque<>();
		Set<Widget> seen = Collections.newSetFromMap(new IdentityHashMap<>());

		queue.add(root);
		seen.add(root);

		while (!queue.isEmpty())
		{
			Widget widget = queue.removeFirst();
			widgets.add(widget);

			pushChildren(queue, seen, widget.getChildren());
			pushChildren(queue, seen, widget.getDynamicChildren());
			pushChildren(queue, seen, widget.getStaticChildren());
			pushChildren(queue, seen, widget.getNestedChildren());
		}

		return widgets;
	}

	private void pushChildren(Deque<Widget> queue, Set<Widget> seen, Widget[] children)
	{
		if (children == null)
		{
			return;
		}

		for (Widget child : children)
		{
			if (child != null && seen.add(child))
			{
				queue.addLast(child);
			}
		}
	}

	private String stripTags(String text)
	{
		return text.replaceAll("<[^>]*>", " ").replace('&', ' ').trim();
	}

	public static class ScanResult
	{
		private final StorageLocation location;
		private final Map<Integer, Integer> quantities;

		public ScanResult(StorageLocation location, Map<Integer, Integer> quantities)
		{
			this.location = location;
			this.quantities = new HashMap<>(quantities);
		}

		public StorageLocation getLocation()
		{
			return location;
		}

		public Map<Integer, Integer> getQuantities()
		{
			return quantities;
		}
	}

	public String debugAllText(int groupId)
	{
		List<Widget> roots = new ArrayList<>();

		for (int childId = 0; childId < 256; childId++)
		{
			Widget w = client.getWidget(groupId, childId);
			if (w != null)
			{
				roots.add(w);
			}
		}

		if (roots.isEmpty())
		{
			return "<no roots>";
		}

		StringBuilder sb = new StringBuilder();

		for (Widget root : roots)
		{
			for (Widget widget : traverse(root))
			{
				String text = widget.getText();
				if (text != null && !text.isEmpty())
				{
					sb.append(' ')
							.append(stripTags(text).toLowerCase(Locale.ENGLISH));
				}
			}
		}

		String result = sb.toString().trim();
		return result.isEmpty() ? "<no text>" : result;
	}
}

package com.wheresmystuff;

import java.time.Duration;
import java.time.Instant;

public class SnapshotMetadata
{
	private long lastSeenEpochMillis;
	private boolean everSeen;

	public long getLastSeenEpochMillis()
	{
		return lastSeenEpochMillis;
	}

	public void setLastSeenEpochMillis(long lastSeenEpochMillis)
	{
		this.lastSeenEpochMillis = lastSeenEpochMillis;
	}

	/**
	 * Compatibility getter for panel code.
	 */
	public long getLastUpdated()
	{
		return lastSeenEpochMillis;
	}

	public boolean isEverSeen()
	{
		return everSeen;
	}

	public void setEverSeen(boolean everSeen)
	{
		this.everSeen = everSeen;
	}

	public void markSeenNow()
	{
		everSeen = true;
		lastSeenEpochMillis = System.currentTimeMillis();
	}

	public DataFreshness freshness(Duration staleAfter, Duration warningAfter)
	{
		if (!everSeen)
		{
			return DataFreshness.NEVER_SEEN;
		}

		Duration age = Duration.between(
				Instant.ofEpochMilli(lastSeenEpochMillis),
				Instant.now()
		);

		if (age.compareTo(staleAfter) >= 0)
		{
			return DataFreshness.OUT_OF_DATE;
		}

		if (age.compareTo(warningAfter) >= 0)
		{
			return DataFreshness.MAYBE_STALE;
		}

		return DataFreshness.FRESH;
	}
}

package com.wheresmystuff;

public class EquipmentStats
{
    private final int slot;
    private final boolean twoHanded;

    private final int stab;
    private final int slash;
    private final int crush;
    private final int magic;
    private final int ranged;

    private final int stabDef;
    private final int slashDef;
    private final int crushDef;
    private final int magicDef;
    private final int rangedDef;

    private final int meleeStr;
    private final int rangedStr;
    private final int magicDmg;
    private final int prayer;

    public EquipmentStats(
            int slot,
            boolean twoHanded,
            int stab, int slash, int crush, int magic, int ranged,
            int stabDef, int slashDef, int crushDef, int magicDef, int rangedDef,
            int meleeStr, int rangedStr, int magicDmg, int prayer)
    {
        this.slot = slot;
        this.twoHanded = twoHanded;
        this.stab = stab;
        this.slash = slash;
        this.crush = crush;
        this.magic = magic;
        this.ranged = ranged;
        this.stabDef = stabDef;
        this.slashDef = slashDef;
        this.crushDef = crushDef;
        this.magicDef = magicDef;
        this.rangedDef = rangedDef;
        this.meleeStr = meleeStr;
        this.rangedStr = rangedStr;
        this.magicDmg = magicDmg;
        this.prayer = prayer;
    }

    public boolean hasAnyBonus()
    {
        return stab != 0 || slash != 0 || crush != 0 || magic != 0 || ranged != 0
                || stabDef != 0 || slashDef != 0 || crushDef != 0 || magicDef != 0 || rangedDef != 0
                || meleeStr != 0 || rangedStr != 0 || magicDmg != 0 || prayer != 0;
    }

    public EquipmentStats difference(EquipmentStats equipped)
    {
        if (equipped == null)
        {
            return this;
        }

        return new EquipmentStats(
                slot,
                twoHanded,
                stab - equipped.stab,
                slash - equipped.slash,
                crush - equipped.crush,
                magic - equipped.magic,
                ranged - equipped.ranged,
                stabDef - equipped.stabDef,
                slashDef - equipped.slashDef,
                crushDef - equipped.crushDef,
                magicDef - equipped.magicDef,
                rangedDef - equipped.rangedDef,
                meleeStr - equipped.meleeStr,
                rangedStr - equipped.rangedStr,
                magicDmg - equipped.magicDmg,
                prayer - equipped.prayer
        );
    }

    public int getSlot() { return slot; }
    public boolean isTwoHanded() { return twoHanded; }

    public int getStab() { return this.stab; }
    public int getCrush() { return this.crush; }
    public int getSlash() { return this.slash; }
    public int getMagic() { return this.magic; }
    public int getRanged() { return this.ranged; }

    public int getStabDef() { return this.stabDef; }
    public int getCrushDef() { return this.crushDef; }
    public int getSlashDef() { return this.slashDef; }
    public int getMagicDef() { return this.magicDef; }
    public int getRangedDef() { return this.rangedDef; }

    public int getMeleeStr() { return this.meleeStr; }
    public int getMagicDmg() { return this.magicDmg; }
    public int getRangedStr() { return this.rangedStr; }
    public int getPrayer() { return this.prayer; }
}

